  "claims": [
    {
      "claim": "The query is a 3-methoxy-N-methyl-morphinan-6-one (hydrocodone skeleton); the closest L6 hepatic-clearance analogs are codeine and dihydrocodeine, which show low-to-moderate intrinsic/hepatic clearance (codeine HLM CLint,u 2.44–2.53 µl/min/mg; dihydrocodeine model CLhep 0.328 L/min), not threshold-limiting first-pass loss.",
      "card_ids": ["C229", "C251"]
    },
    {
      "claim": "Morphine, the closest L1 comparator with measured oral F, has healthy-subject F ~47% despite measurable hepatic clearance (perfused rat liver 26 mL/min; human hepatocyte CLint 28 µl/min/10^6), so moderate hepatic clearance does not imply F<20%.",
      "card_ids": ["C51", "C245", "C238"]
    },
    {
      "claim": "Codeine shows high Caco-2 permeability and rapid, almost complete human intestinal absorption (>90% F_abs), morphine is rapidly absorbed from the small intestine with only weak P-gp efflux, and samidorphan (another morphinan) has 69% oral F; absorption is not threshold-limiting.",
      "card_ids": ["C144", "C168", "C170", "C220", "C183", "C222", "C01"]
    },
    {
      "claim": "Dextromethorphan high HLM intrinsic-clearance records are less transferable because the query retains the 4,5-epoxy-6-one morphinan scaffold; high intrinsic clearance alone is not affirmative evidence for F<20%.",
      "card_ids": ["C253", "C247", "C234"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C229", "C251", "C245", "C238"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for hydrocodone; endpoint support is from structural analogs (morphine, codeine, samidorphan).",
    "No query-specific hepatic clearance or metabolic-stability experiment; L6 records are for codeine, dihydrocodeine, morphine, dextromethorphan, and other morphinans.",
    "Dextromethorphan high-clearance records introduce uncertainty, but their scaffold lacks the 4,5-epoxy-6-one system of the query.",
    "No formulation, dose, prandial state, or CYP2D6/CYP3A4 phenotype data for the query."
  ],
  "decision_summary": "Prediction remains high and is strengthened by L6: the closest hepatic-clearance analogs (codeine, dihydrocodeine, morphine) show low-to-moderate clearance, and morphine's healthy oral F ~47% shows this is not threshold-limiting. Dextromethorphan high-clearance records are less transferable. Combined with codeine's high permeability/>90% absorption and morphine's rapid absorption/weak efflux, F>=20% is better supported; no affirmative evidence supports F<20%."
}

